mapper.update:
WITH restored AS (
    UPDATE knowledge_branch_scopes s SET mode=h.mode,branch_ids=h.branch_ids
    FROM knowledge_branch_scope_history h, knowledge_cards k
    WHERE s.card_id=h.card_id AND k.id=s.card_id AND k.repo_id=#{repositoryId}
      AND h.card_id=#{cardId} AND h.revision=#{sourceRevision}
    RETURNING s.card_id,s.mode,s.branch_ids
)
UPDATE knowledge_branch_scope_history h SET mode=r.mode,branch_ids=r.branch_ids FROM restored r
WHERE h.card_id=r.card_id AND h.revision=#{targetRevision}
